const formData = $('Form Trigger - Dados do Gasto').item.json;
const apiData = $input.item.json;

const moedaInput = formData['Moeda'].split(' ')[0];
const valorOriginal = parseFloat(formData['Valor do Gasto']);

let valorEmBRL = valorOriginal;
let cotacaoInfo = 'Gasto já em Real Brasileiro';
let taxaCambio = 1;

if (moedaInput !== 'BRL') {
  const chaveAPI = moedaInput === 'USD' ? 'USDBRL' : 'EURBRL';
  if (apiData[chaveAPI]) {
    taxaCambio = parseFloat(apiData[chaveAPI].bid);
    valorEmBRL = valorOriginal * taxaCambio;
    const nomeCompleto = moedaInput === 'USD' ? 'Dólar Americano' : 'Euro';
    cotacaoInfo = `1 ${nomeCompleto} = R$ ${taxaCambio.toFixed(4)} (cotação atual)`;
  }
}

const hoje = new Date();
const dataGasto = new Date(formData['Data do Gasto']);
const diasAtras = Math.floor((hoje - dataGasto) / (1000 * 60 * 60 * 24));
let periodoTexto = diasAtras === 0 ? 'hoje' : diasAtras === 1 ? 'ontem' : `há ${diasAtras} dias`;

const recorrente = formData['É um gasto recorrente?'] || 'Não';
let projecaoMensal = valorEmBRL;
if (recorrente === 'Sim - Diário') projecaoMensal = valorEmBRL * 30;
else if (recorrente === 'Sim - Semanal') projecaoMensal = valorEmBRL * 4;
else if (recorrente === 'Sim - Mensal') projecaoMensal = valorEmBRL;

return {
  json: {
    valorOriginal,
    moedaOriginal: moedaInput,
    valorEmBRL: parseFloat(valorEmBRL.toFixed(2)),
    cotacaoInfo,
    taxaCambio,
    categoria: formData['Categoria'],
    descricao: formData['Descrição do Gasto'],
    dataGasto: formData['Data do Gasto'],
    periodoTexto,
    recorrente,
    projecaoMensal: parseFloat(projecaoMensal.toFixed(2)),
    resumoContexto: `DADOS DO GASTO:\n- Valor: ${moedaInput} ${valorOriginal} (R$ ${valorEmBRL.toFixed(2)})\n- Câmbio: ${cotacaoInfo}\n- Categoria: ${formData['Categoria']}\n- Descrição: ${formData['Descrição do Gasto']}\n- Data: ${formData['Data do Gasto']} (${periodoTexto})\n- Recorrência: ${recorrente}\n- Projeção mensal: R$ ${projecaoMensal.toFixed(2)}`
  }
};

const processedData = $('Processar e Calcular Dados').first().json;
const geminiResponse = $input.first().json;

 

const analiseTexto =
  geminiResponse.output ||
  geminiResponse.content ||
  geminiResponse.text ||
  geminiResponse.response ||
  JSON.stringify(geminiResponse);

 

const relatorioFinal = {
  status: 'sucesso',
  timestamp: new Date().toISOString(),
  gasto: {
    descricao: processedData.descricao,
    categoria: processedData.categoria,
    valorOriginal: `${processedData.moedaOriginal} ${processedData.valorOriginal}`,
    valorBRL: `R$ ${Number(processedData.valorEmBRL).toFixed(2)}`,
    cotacao: processedData.cotacaoInfo,
    data: processedData.dataGasto,
    recorrente: processedData.recorrente,
    projecaoMensal: `R$ ${Number(processedData.projecaoMensal).toFixed(2)}`,
    projecaoAnual: `R$ ${(Number(processedData.projecaoMensal) * 12).toFixed(2)}`
  },
  analiseGemini: analiseTexto,
  mensagemFormatada: `
ANÁLISE DO GASTO

 

Resumo
Descrição: ${processedData.descricao}
Categoria: ${processedData.categoria}
Data: ${processedData.dataGasto}

 

Valores
Valor informado: ${processedData.moedaOriginal} ${processedData.valorOriginal}
Valor convertido: R$ ${Number(processedData.valorEmBRL).toFixed(2)}
Cotação usada: ${processedData.cotacaoInfo}

 

Recorrência
Frequência: ${processedData.recorrente}
Projeção mensal: R$ ${Number(processedData.projecaoMensal).toFixed(2)}
Projeção anual: R$ ${(Number(processedData.projecaoMensal) * 12).toFixed(2)}

 

Análise financeira
${analiseTexto}

 

Recomendação
Avalie se esse gasto é essencial. Caso seja recorrente, compare alternativas mais baratas para reduzir o impacto mensal.
`
};

 

return [
  {
    json: relatorioFinal
  }
];
